// The payload must come from the trigger, not from $input: 'Auth OK?' and now
// 'Tenant For JWT User' sit in between, so $input here is the tenant lookup's
// response, not the request.
// $('Webhook - Ask AI') THROWS if that node did not run in this execution --
// it does NOT return undefined -- so the lookup is wrapped in try/catch.
let raw;
try {
  raw = $('Webhook - Ask AI').first().json;
} catch (e) {
  raw = $input.first().json;   // direct / sub-workflow / manual call
}

const body = raw.body || raw;
const question = String(body.question || body.query || body.q || '').trim();

if (!question) {
  throw new Error('No question provided. POST a JSON body like { "question": "What is our warranty policy?" }');
}

// ---- TENANT (2 Sep 2026) --------------------------------------------------
// public.search_rag_documents is SECURITY INVOKER on purpose, but n8n calls it
// as service_role, which is BYPASSRLS -- so for this workflow the p_tenant
// ARGUMENT is the entire boundary. The 2-arg overload we used before derives
// the tenant from nexus_scoped_tenant_id(), which is null for service_role;
// with a second dealership active that function returns nothing at all and
// Ask-AI answers 'no documents' to everyone. Naming the tenant fixes both the
// leak and the outage.
//
// The signal is the Supabase user behind the VERIFIED JWT, mapped through
// tenant_members by the node before this one. That is a real identity: the
// person asking works for that dealership. It is not the request body, which
// the caller controls.
const NEXUS_BUILTIN = { 'default': 'fff6a2b5-cfd5-4460-8383-875bc5826de0' };  // ALBA CARS
const NEXUS_UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
let nexusMap = {};
try { nexusMap = JSON.parse(String($env.NEXUS_TENANT_MAP || '')) || {}; } catch (e) { nexusMap = {}; }
if (!nexusMap || typeof nexusMap !== 'object' || !Object.keys(nexusMap).length) nexusMap = NEXUS_BUILTIN;
const nexusKeys = Object.keys(nexusMap);

let tenant = '';
let tenantSource = '';
try {
  const row = $('Tenant For JWT User').all().map(i => i.json).find(x => x && x.tenant_id);
  if (row) { tenant = String(row.tenant_id); tenantSource = 'jwt_tenant_member'; }
} catch (e) { /* manual run: that node did not execute */ }
// Sole configured dealership: name it rather than send null and rely on the
// function's own one-tenant fallback. Two or more and an unknown asker gets
// null, which makes the function return nothing -- fail closed, by design.
if (!NEXUS_UUID.test(tenant) && nexusKeys.length === 1) {
  tenant = String(nexusMap[nexusKeys[0]] || '');
  tenantSource = 'sole_configured_tenant';
}
if (!NEXUS_UUID.test(tenant)) { tenant = null; tenantSource = 'unresolved'; }

// Retrieval now lives in Postgres: public.search_rag_documents(q, match_limit,
// p_tenant). It ranks with ts_rank_cd and falls back to per-term trigram
// matching for typos. This node no longer builds a tsquery or strips stopwords
// -- doing that here is exactly what made short questions return nothing.
return [{ json: { question, tenant_id: tenant, tenant_source: tenantSource } }];

const question = $('Extract Question').first().json.question;

// search_rag_documents returns a ranked array; n8n splits it one item per row.
const rows = $input.all()
  .map(i => i.json)
  .filter(r => r && r.content);

/* ---------------------------------------------------------------------------
   WHY THIS NODE CHANGED (30 Aug 2026)
   The old build concatenated every retrieved row and then did
   `context.substring(0, 8000)`. Two things went wrong and neither was visible
   downstream:
     - the LAST sources were cut off the prompt entirely while still being
       reported to the dashboard as sources of the answer, and
     - whichever source straddled the 8000th character was cut mid-sentence,
       so the model was invited to cite text it had only half seen.
   The budget is now spent per source, cut on a word boundary, and every cut is
   RECORDED on the source itself (`included_in_prompt`, `truncated`,
   `chars_fed`). A source the model never saw can no longer be presented as one
   it used.
--------------------------------------------------------------------------- */
const TOTAL_BUDGET = 8000;
const OVERHEAD     = 80;    // "[S1] Title / Section:" plus the blank line after it
const MIN_USEFUL   = 500;   // under this a block is a stub the model can cite blind

/* ---- How the 8000 characters are handed out ------------------------------
   Two rules, in this order.

   1. CAP THE NUMBER OF BLOCKS. At most floor(8000 / (500 + 80)) = 13 sections
      can each be given a genuinely usable amount of text. Ranked lower than
      that and a section is left OUT of the prompt entirely and marked
      `included_in_prompt: false`. A 300-character stub of a clause is worse
      than no stub: the model can cite it having seen none of the part that
      matters.

   2. WATER-FILL THE REST. A short section takes only what it needs and hands
      the surplus back, so a four-line section does not reserve a sixth of the
      budget, and a long one is cut only after every short one is satisfied.
      When everything fits, nothing is truncated at all - the common case, and
      one the old `substring(0, 8000)` never managed.
-------------------------------------------------------------------------- */
const MAX_BLOCKS = Math.max(1, Math.floor(TOTAL_BUDGET / (MIN_USEFUL + OVERHEAD)));
const keptCount  = Math.min(rows.length, MAX_BLOCKS);

const need  = rows.map(r => String(r.content == null ? '' : r.content).length + OVERHEAD);
const alloc = rows.map(() => 0);

let pool = TOTAL_BUDGET;
let open_ = [];
for (let i = 0; i < keptCount; i++) open_.push(i);
while (open_.length) {
  const share = Math.floor(pool / open_.length);
  const satisfied = open_.filter(i => need[i] <= share);
  if (!satisfied.length) { open_.forEach(i => { alloc[i] = share; }); break; }
  satisfied.forEach(i => { alloc[i] = need[i]; pool -= need[i]; });
  open_ = open_.filter(i => need[i] > share);
}

function clip(text, limit) {
  const s = String(text == null ? '' : text);
  if (s.length <= limit) return { text: s, truncated: false, kept: s.length, total: s.length };
  const cut = s.slice(0, limit);
  const boundary = Math.max(cut.lastIndexOf('. '), cut.lastIndexOf('\n'), cut.lastIndexOf(' '));
  const body = (boundary > limit * 0.5 ? cut.slice(0, boundary + 1) : cut).replace(/\s+$/, '');
  return { text: body + ' [...truncated here, open the source document]', truncated: true, kept: body.length, total: s.length };
}

let context = '';
let used = 0;
const sources = [];

rows.forEach((doc, i) => {
  const ref     = 'S' + (i + 1);
  const title   = doc.doc_title || 'Document';
  const section = doc.section ? ' / ' + doc.section : '';

  // A stable handle back to the exact row that was fed in. The RPC may or may
  // not project an id column; if it does not this stays null and the section +
  // page below are the only handle there is. That is stated, not hidden.
  const row_id = doc.id != null ? doc.id
               : doc.doc_id != null ? doc.doc_id
               : doc.document_id != null ? doc.document_id
               : doc.chunk_id != null ? doc.chunk_id
               : null;

  const base = {
    ref: ref,
    title: title,
    section: doc.section || null,
    source_file: doc.source_file || null,
    page_number: doc.page_number != null ? doc.page_number : null,
    row_id: row_id,
    match_type: doc.match_type || null,
    rank: doc.rank != null ? doc.rank : null
  };

  const room = alloc[i] - OVERHEAD;
  if (i >= keptCount || room <= 0) {
    sources.push(Object.assign({}, base, {
      included_in_prompt: false,
      truncated: false,
      chars_fed: 0,
      chars_total: String(doc.content || '').length,
      content: null,
      note: 'Retrieved by the search but NOT sent to the model: only the top ' + keptCount + ' of ' + rows.length + ' matches fit in the ' + TOTAL_BUDGET + '-character context budget at a usable size. The answer cannot have come from this section.'
    }));
    return;
  }

  const c = clip(doc.content, room);
  const block = '[' + ref + '] ' + title + section + ':\n' + c.text + '\n\n';
  context += block;
  used += block.length;

  sources.push(Object.assign({}, base, {
    included_in_prompt: true,
    truncated: c.truncated,
    chars_fed: c.kept,
    chars_total: c.total,
    // The opening of the exact text the model was handed, so a rep can compare
    // the answer against the source without leaving the dashboard.
    content: c.text.slice(0, 400)
  }));
});

const no_match = rows.length === 0;
if (no_match) {
  context = 'No relevant documents were found in the knowledge base for this question.';
}

/* Every numeric token that appears in the text the model was ACTUALLY given.
   `Format Response` diffs the answer against this. It is not claim
   verification - it only covers numbers - but numbers are the part of a policy
   answer that does the damage when invented: a refund window, an APR, a
   mileage cap. */
const context_numbers = Array.from(new Set(
  context.replace(/,(?=\d{3}\b)/g, '').match(/\d+(?:\.\d+)?/g) || []
));

return [{ json: {
  question: question,
  context: context,
  sources: sources,
  sources_in_prompt: sources.filter(s => s.included_in_prompt).map(s => s.ref),
  docs_in_prompt: sources.filter(s => s.included_in_prompt).length,
  doc_count: sources.length,
  context_numbers: context_numbers,
  context_chars: context.length,
  no_match: no_match,
  no_match_message: 'Nothing in the knowledge base matched that. It currently covers the warranty policy, the HR handbook, sales compensation and the trade-in appraisal SOP - try asking in a full sentence, for example "What is our warranty on a new car?"'
} }];

const aiResponse = $input.first().json || {};
const ctx = $('Build RAG Context').first().json;

const retrieved = Array.isArray(ctx.sources) ? ctx.sources : [];

/* ---------------------------------------------------------------------------
   WHY THIS NODE CHANGED (30 Aug 2026)
   `sources` used to be the retrieval result copied wholesale. The dashboard
   renders that list directly beside the answer, so a model that ignored the
   context and answered from its own training knowledge was displayed next to
   four real document titles and page numbers, and read as company policy.
   `sources` now means ONE thing only: the blocks the model itself marked.
   Retrieval output moves to `retrieved_sources`, under a different key so no
   renderer can mistake it for a citation. An empty `sources` is a real, useful
   and honest value - it is the dashboard's cue to say nothing was cited.
--------------------------------------------------------------------------- */

let answer = '';
let grounding_state = null;   // cited | uncited | declined | no_documents | model_unavailable
let model_error = null;

if (ctx.no_match) {
  answer = ctx.no_match_message;
  grounding_state = 'no_documents';
} else if (aiResponse.error !== undefined) {
  // Reached when BOTH model tiers are down: the backup node now swallows its
  // failure (onError: continueRegularOutput) instead of stopping the workflow
  // and leaving the caller hanging on the 300 s execution timeout.
  const e = aiResponse.error;
  model_error = typeof e === 'string' ? e : JSON.stringify(e);
  answer = 'This question was NOT answered. Both model tiers failed, so nothing here comes from your documents. '
         + 'The knowledge-base search did find ' + ctx.doc_count + ' matching section(s) - they are listed below as documents searched, '
         + 'and they have not been read by anything. Retry in a moment, or open them yourself. '
         + 'Provider detail: ' + String(model_error).substring(0, 300);
  grounding_state = 'model_unavailable';
} else if (aiResponse.choices && aiResponse.choices[0] && aiResponse.choices[0].message
           && String(aiResponse.choices[0].message.content || '').trim()) {
  answer = String(aiResponse.choices[0].message.content).trim();
} else {
  answer = 'The model returned an empty answer even though ' + ctx.doc_count
         + ' document section(s) matched. Nothing here is sourced. Please try rephrasing the question.';
  grounding_state = 'model_unavailable';
}

// ---- Citation gating -------------------------------------------------------
const byRef = new Map(retrieved.map(s => [String(s.ref).toUpperCase(), s]));
const cited_refs = [];
const invalid_refs = [];

if (grounding_state === null) {
  // Parsed liberally on purpose. A model that writes [Source 2] or (Source 2)
  // instead of [S2] has still named a source, and punishing the formatting
  // would produce a FALSE "uncited", which is its own kind of dishonesty.
  const re = /\[\s*(?:S|SOURCE)?\s*(\d{1,2})\s*\]|\(\s*SOURCE\s*(\d{1,2})\s*\)/gi;
  let m;
  while ((m = re.exec(answer)) !== null) {
    const ref = 'S' + (m[1] || m[2]);
    if (byRef.has(ref)) { if (cited_refs.indexOf(ref) === -1) cited_refs.push(ref); }
    else if (invalid_refs.indexOf(ref) === -1) invalid_refs.push(ref);
  }
  if (/^\s*NOT_IN_CONTEXT\b/i.test(answer)) {
    grounding_state = 'declined';
    // Render the refusal as a sentence, not as a protocol token.
    const rest = answer.replace(/^\s*NOT_IN_CONTEXT\b[\s:.-]*/i, '').trim();
    answer = 'The retrieved documents do not answer this question, so nothing was answered from them.'
           + (rest ? ' ' + rest : '')
           + ' The sections the search did return are listed below - open them if you think the answer should be in one of them.';
  } else {
    grounding_state = cited_refs.length ? 'cited' : 'uncited';
  }
}

const cited_sources = cited_refs.map(r => byRef.get(r));

// ---- Figure check (deterministic, advisory) --------------------------------
/* This is NOT claim verification and is not presented as one. It answers a
   single narrow question that is cheap enough to answer on a shared vCPU:
   does every number in the answer appear somewhere in the text the model was
   given? A number that does not is either arithmetic the model did, or an
   invention. Both are worth a human eye before the figure is repeated to a
   customer. Citation markers and list markers are stripped first so they
   cannot be mistaken for figures. */
const answerForNums = String(answer)
  .replace(/\[\s*(?:S|SOURCE)?\s*\d{1,2}\s*\]/gi, ' ')
  .replace(/\(\s*SOURCE\s*\d{1,2}\s*\)/gi, ' ')
  .replace(/^\s*\d{1,2}[.)]\s+/gm, ' ');

const ctxNums = new Set(ctx.context_numbers || []);
const answerNums = Array.from(new Set(
  answerForNums.replace(/,(?=\d{3}\b)/g, '').match(/\d+(?:\.\d+)?/g) || []
));
const checkable = (grounding_state === 'cited' || grounding_state === 'uncited');
const unsupported_figures = checkable ? answerNums.filter(n => !ctxNums.has(n)) : [];

return [{ json: {
  question: ctx.question,

  answer: answer,

  // ONLY the blocks the model marked. May legitimately be empty.
  sources: cited_sources,

  // Everything retrieval returned, including blocks that never reached the
  // model. Deliberately a different key from `sources`.
  retrieved_sources: retrieved,

  grounding: {
    state: grounding_state,
    cited_refs: cited_refs,
    invalid_refs: invalid_refs,
    retrieved_count: retrieved.length,
    sent_to_model: ctx.sources_in_prompt || [],
    dropped_from_prompt: retrieved.filter(s => !s.included_in_prompt).map(s => s.ref),
    truncated_sources: retrieved.filter(s => s.truncated).map(s => s.ref),
    unsupported_figures: unsupported_figures,
    method: 'The model was instructed to mark each sourced sentence with [S#]. Only markers it actually emitted are rendered as citations. A marker is the model CLAIMING a source, not proof the sentence came from it. Figures are additionally diffed against the retrieved text.'
  },

  documents_consulted: ctx.doc_count,
  documents_cited: cited_sources.length,
  no_match: !!ctx.no_match,
  model: aiResponse.model || null,
  model_error: model_error,
  timestamp: new Date().toISOString()
} }];

// Verify every node whose success this audit row is about to claim.
// 'Respond to Webhook' swallows with onError: continueRegularOutput: if the
// response never reaches the caller the run still carries on to 'Audit Log'.
const CLAIMED = [
  { node: 'Respond to Webhook', what: 'HTTP answer returned to the caller', critical: true },
];

function check(c) {
  let items;
  try { items = $(c.node).all(); }
  catch (e) { return Object.assign({}, c, { ok: false, why: 'node did not run on this branch' }); }
  if (!items.length) return Object.assign({}, c, { ok: false, why: 'node produced no items' });
  const j = items[0].json || {};
  if (j.error !== undefined) {
    const m = (j.error && (j.error.message || j.error.description)) || j.error;
    return Object.assign({}, c, { ok: false, why: String(m).slice(0, 300) });
  }
  return Object.assign({}, c, { ok: true });
}

const results = check ? CLAIMED.map(check) : [];
const dropped = results.filter(r => !r.ok);
const fatal   = dropped.filter(r => r.critical);

let status = fatal.length   ? 'FAILED'
           : dropped.length ? 'PARTIAL'
           : 'SUCCESS';

const base = $input.first().json || {};

let fr = {};
try { fr = $('Format Response').first().json || {}; } catch (e) { fr = {}; }

/* 30 Aug 2026: delivering an HTTP 200 that says "both model tiers failed" is a
   delivered response, not a successful answer, and the audit row must not read
   SUCCESS for it. Same family of defect as the citations: do not record an
   outcome the run did not achieve. */
const g = base.grounding || fr.grounding || null;
const gstate = g ? g.state : null;
const extra = [];
if (gstate === 'model_unavailable') {
  if (status === 'SUCCESS') status = 'PARTIAL';
  extra.push('no model answered - response delivered but not sourced');
}
if (gstate === 'uncited') extra.push('answer carried no citation markers - shown to the user as uncited');
if (gstate === 'declined') extra.push('model declined: NOT_IN_CONTEXT');
if (g && g.dropped_from_prompt && g.dropped_from_prompt.length)
  extra.push('retrieved but not sent to the model: ' + g.dropped_from_prompt.join(','));
if (g && g.unsupported_figures && g.unsupported_figures.length)
  extra.push('figures not found in retrieved text: ' + g.unsupported_figures.slice(0, 8).join(','));
if (g && g.invalid_refs && g.invalid_refs.length)
  extra.push('model cited non-existent sources: ' + g.invalid_refs.join(','));

return [{ json: Object.assign({}, base, {
  question: base.question !== undefined ? base.question : (fr.question != null ? fr.question : null),
  documents_consulted: base.documents_consulted !== undefined ? base.documents_consulted : (fr.documents_consulted != null ? fr.documents_consulted : null),
  documents_cited: base.documents_cited !== undefined ? base.documents_cited : (fr.documents_cited != null ? fr.documents_cited : null),
  grounding: g,
  delivery: {
    status: status,
    verified: results.filter(r => r.ok).map(r => r.what),
    dropped:  dropped.map(r => r.what + ' - ' + r.why),
    grounding_state: gstate,
    notes: extra,
    note: (dropped.length
      ? dropped.length + ' of ' + results.length + ' claimed steps did not land'
      : 'all ' + results.length + ' claimed steps verified')
      + (extra.length ? ' | ' + extra.join(' | ') : '')
  }
}) }];
